//! Fixed old wire bytes, not fixtures generated by the current serializer.
use super::*;
use crate::{FsStore, InputCompactionUse, Store, WorkerSessionStore};
use serde_json::{Value, json};
use std::{fs, path::Path};

const V4: &str = include_str!("fixtures/v4-system-inputs.jsonl");
const V1: &str = include_str!("fixtures/v1-system-inputs.jsonl");

fn decode_fixture(version: u32, source: &str, segment: SegmentId) -> Vec<LogEntry> {
    source
        .lines()
        .enumerate()
        .map(|(index, line)| decode_entry(version, line, SessionId::nil(), segment, index).unwrap())
        .collect()
}

fn encode(entries: &[LogEntry]) -> Vec<u8> {
    let mut bytes = Vec::new();
    for entry in entries {
        serde_json::to_writer(&mut bytes, entry).unwrap();
        bytes.push(b'\n');
    }
    bytes
}

fn migrate(entries: &mut [LogEntry]) {
    for entry in entries {
        migrate_system_inputs(entry).unwrap();
        entry.validate_input_metadata().unwrap();
    }
}

fn write_worker(root: &Path, version: u32, source: &[u8]) -> (SessionId, SegmentId) {
    let session = SessionId::now_v7();
    let segment = SegmentId::from_u128(1);
    fs::create_dir_all(root.join("segments")).unwrap();
    fs::write(
        root.join("session.json"),
        serde_json::to_vec(&json!({
            "schema_version": version, "session_id": session,
        }))
        .unwrap(),
    )
    .unwrap();
    fs::write(
        root.join("segments").join(format!("{segment}.jsonl")),
        source,
    )
    .unwrap();
    (session, segment)
}

fn assert_marker(root: &Path, version: u32) {
    let manifest: Value =
        serde_json::from_slice(&fs::read(root.join("session.json")).unwrap()).unwrap();
    assert_eq!(manifest["schema_version"], version);
}

#[test]
fn v4_fixed_wire_preserves_identity_body_payload_public_and_independent_policy() {
    let mut entries = decode_fixture(4, V4, SegmentId::nil());
    let before = entries.clone();
    migrate(&mut entries);
    let schemas = [
        "journal:startup",
        "memory:resident-summary",
        "subject:behavior",
        "skill:activation",
        "feature:invocation-result",
    ];
    let old_wire: Vec<Value> = V4
        .lines()
        .map(|line| serde_json::from_str(line).unwrap())
        .collect();
    for index in 0..5 {
        let LogEntry::AnnotatedSystemItem {
            ts,
            entry,
            extensions,
        } = &entries[index]
        else {
            panic!()
        };
        let old = &old_wire[index];
        let old_item = &old["entry"]["item"];
        let old_metadata: LoggedSessionHistoryMetadata =
            serde_json::from_value(old["entry"]["metadata"].clone()).unwrap();
        let old_ext: Vec<crate::SessionExtension> = old
            .get("extensions")
            .map(|value| serde_json::from_value(value.clone()).unwrap())
            .unwrap_or_default();
        assert_eq!(*ts, old["ts"].as_u64().unwrap());
        assert_eq!(extensions, &old_ext);
        assert!(matches!(entry.item, SystemItem::Input { .. }));
        assert_eq!(
            entry.item.history_text(),
            old_item["body"].as_str().unwrap()
        );
        assert_eq!(entry.metadata.entry_id, old_metadata.entry_id);
        assert_eq!(entry.metadata.origin, old_metadata.origin);
        assert_eq!(entry.metadata.derivation, old_metadata.derivation);
        let metadata = entry.metadata.input_metadata.as_ref().unwrap();
        let public = metadata.public_item().unwrap();
        assert_eq!(public.kind, old_item["kind"].as_str().unwrap());
        assert_eq!(public.body, old_item["body"].as_str().unwrap());
        assert_eq!(
            public.presentation,
            crate::PublicSystemPresentation::Context
        );
        assert_eq!(
            metadata.usage(),
            migration_policy(if index == 0 {
                InputCompactionUse::ReferenceInput
            } else {
                InputCompactionUse::Retain
            })
        );
        let payload = metadata.feature_payload().unwrap();
        assert_eq!(payload.schema(), schemas[index]);
        assert_eq!(payload.version(), 1);
        let value: Value = payload.decode(schemas[index], 1).unwrap();
        // Independently require each frozen owner's typed v1 payload contract.
        match index {
            0 => {
                let _: JournalStartupPayload = payload.decode(schemas[index], 1).unwrap();
            }
            1 => {
                let _: ResidentSummaryPayload = payload.decode(schemas[index], 1).unwrap();
            }
            2 => {
                let _: SubjectBehaviorPayload = payload.decode(schemas[index], 1).unwrap();
            }
            3 => {
                let _: SkillActivationPayload = payload.decode(schemas[index], 1).unwrap();
            }
            4 => {
                let _: InvocationResultPayload = payload.decode(schemas[index], 1).unwrap();
            }
            _ => unreachable!(),
        }
        let mut expected = old_item.clone();
        expected.as_object_mut().unwrap().remove("kind");
        expected.as_object_mut().unwrap().remove("body");
        // Optional provenance is an explicit Option in the v1 payload contract.
        if index == 1 {
            expected["prompt_provenance"] = Value::Null;
        }
        if index == 4 {
            let result: protocol::FeatureInvocationResult =
                serde_json::from_value(old_item["result"].clone()).unwrap();
            let typed: InvocationResultPayload = payload.decode(schemas[index], 1).unwrap();
            assert_eq!(typed.result, result);
            // Preserve the protocol's typed serialization contract, including
            // its canonical representation of optional result context.
            expected["result"] = serde_json::to_value(result).unwrap();
        }
        assert_eq!(value, expected);
        assert!(value.get("body").is_none());
    }
    let LogEntry::AnnotatedUserInput { history, .. } = &entries[5] else {
        panic!()
    };
    let LogEntry::AnnotatedUserInput { history: old, .. } = &before[5] else {
        panic!()
    };
    for (index, compaction) in [
        InputCompactionUse::ReferenceInput,
        InputCompactionUse::OpeningSummary,
        InputCompactionUse::Retain,
    ]
    .into_iter()
    .enumerate()
    {
        assert_eq!(history[index].item, old[index].item);
        assert_eq!(
            history[index].metadata.entry_id,
            old[index].metadata.entry_id
        );
        assert_eq!(history[index].metadata.origin, old[index].metadata.origin);
        assert_eq!(
            history[index].metadata.derivation,
            old[index].metadata.derivation
        );
        let metadata = history[index].metadata.input_metadata.as_ref().unwrap();
        assert_eq!(metadata.usage(), migration_policy(compaction));
        assert!(metadata.public_item().is_none());
        assert!(metadata.feature_payload().is_none());
    }
    // Core notification is unchanged; existing generic Input and unknown valid
    // owner payload are retained without decoding/reclassifying a Feature.
    assert_eq!(encode(&entries[6..]), encode(&before[6..]));
    let once = encode(&entries);
    migrate(&mut entries);
    assert_eq!(encode(&entries), once);
}

#[test]
fn v1_through_v4_worker_migration_reopen_and_mixed_file_retry() {
    for version in 1..=4 {
        let source = if version <= 2 { V1 } else { V4 };
        let root = tempfile::tempdir().unwrap();
        let (session, segment) = write_worker(root.path(), version, source.as_bytes());
        let path = root
            .path()
            .join("segments")
            .join(format!("{segment}.jsonl"));
        // Simulate an interrupted publication: v5 records precede legacy records
        // in one file, and a fully new file coexists with an untouched old file.
        let mut converted = decode_fixture(version, source, segment);
        migrate(&mut converted);
        let mut mixed = encode(&converted[..1]);
        mixed.extend_from_slice(source.split_once('\n').unwrap().1.as_bytes());
        fs::write(&path, &mixed).unwrap();
        let new_path = root
            .path()
            .join("segments")
            .join(format!("{}.jsonl", SegmentId::from_u128(2)));
        let new_bytes = encode(&converted);
        fs::write(&new_path, &new_bytes).unwrap();
        let old_path = root
            .path()
            .join("segments")
            .join(format!("{}.jsonl", SegmentId::from_u128(3)));
        fs::write(&old_path, source).unwrap();

        let marker = fs::read(root.path().join("session.json")).unwrap();
        WorkerSessionStore::validate_migration(root.path()).unwrap();
        assert_eq!(fs::read(&path).unwrap(), mixed);
        assert_eq!(fs::read(&old_path).unwrap(), source.as_bytes());
        assert_eq!(fs::read(root.path().join("session.json")).unwrap(), marker);
        let store = WorkerSessionStore::new(root.path()).unwrap();
        assert_marker(root.path(), 6);
        let restored = store.read_all(session, segment).unwrap();
        assert_eq!(encode(&restored), new_bytes);
        assert_eq!(fs::read(&new_path).unwrap(), new_bytes);
        let once = fs::read(&path).unwrap();
        let old_once = fs::read(&old_path).unwrap();
        drop(store);
        let reopened = WorkerSessionStore::new(root.path()).unwrap();
        assert_eq!(encode(&reopened.read_all(session, segment).unwrap()), once);
        assert_eq!(fs::read(&path).unwrap(), once);
        assert_eq!(fs::read(&old_path).unwrap(), old_once);
    }
}

#[test]
fn all_segments_preflight_keeps_old_bytes_on_decode_or_conversion_failure() {
    let mut oversized: Value = serde_json::from_str(V4.lines().next().unwrap()).unwrap();
    oversized["entry"]["item"]["snapshot"] =
        json!({"large": "x".repeat(crate::input_metadata::MAX_FEATURE_PAYLOAD_BYTES + 1)});
    let mut unknown: Value = serde_json::from_str(V4.lines().next().unwrap()).unwrap();
    unknown["entry"]["item"]["kind"] = json!("unsupported_future_feature");
    let mut malformed = unknown.clone();
    malformed["entry"]["item"] = json!({"kind":"journal_startup", "body":"missing snapshot"});
    let mut missing_metadata: Value = serde_json::from_str(V4.lines().last().unwrap()).unwrap();
    missing_metadata["entry"]["metadata"]
        .as_object_mut()
        .unwrap()
        .remove("system_input");
    let mut missing_input = missing_metadata.clone();
    missing_input["entry"]["metadata"]["origin"] = json!({"kind":"legacy_unknown"});
    let mut invalid_policy: Value = serde_json::from_str(V4.lines().last().unwrap()).unwrap();
    invalid_policy["entry"]["metadata"]["system_input"]["usage"]["compaction"] = json!("unknown");
    let mut invalid_payload = invalid_policy.clone();
    invalid_payload["entry"]["metadata"]["system_input"]["usage"]["compaction"] = json!("retain");
    invalid_payload["entry"]["metadata"]["system_input"]["feature_payload"]["version"] = json!(0);
    let mut flat_provided: Value = serde_json::from_str(V4.lines().nth(5).unwrap()).unwrap();
    flat_provided["history"][0]["metadata"]["origin"] =
        json!({"kind":"provided", "producer":"owner"});
    for bad in [
        "{broken-json}\n".to_owned(),
        format!("{}\n", oversized),
        format!("{}\n", unknown),
        format!("{}\n", malformed),
        format!("{}\n", missing_metadata),
        format!("{}\n", invalid_policy),
        format!("{}\n", invalid_payload),
        format!("{}\n", flat_provided),
        format!("{}\n", missing_input),
    ] {
        let root = tempfile::tempdir().unwrap();
        let (_, segment) = write_worker(root.path(), 4, V4.as_bytes());
        let first = root
            .path()
            .join("segments")
            .join(format!("{segment}.jsonl"));
        let later = root
            .path()
            .join("segments")
            .join(format!("{}.jsonl", SegmentId::from_u128(2)));
        fs::write(&later, &bad).unwrap();
        let marker = fs::read(root.path().join("session.json")).unwrap();
        assert!(WorkerSessionStore::validate_migration(root.path()).is_err());
        assert!(WorkerSessionStore::new(root.path()).is_err());
        assert_eq!(fs::read(&first).unwrap(), V4.as_bytes());
        assert_eq!(fs::read(&later).unwrap(), bad.as_bytes());
        assert_eq!(fs::read(root.path().join("session.json")).unwrap(), marker);
    }
}

#[test]
fn unsupported_schema_preserves_all_old_bytes() {
    for version in [0, 7, 99] {
        let root = tempfile::tempdir().unwrap();
        let (_, segment) = write_worker(root.path(), version, V4.as_bytes());
        let path = root
            .path()
            .join("segments")
            .join(format!("{segment}.jsonl"));
        let marker = fs::read(root.path().join("session.json")).unwrap();
        assert!(WorkerSessionStore::new(root.path()).is_err());
        assert_eq!(fs::read(&path).unwrap(), V4.as_bytes());
        assert_eq!(fs::read(root.path().join("session.json")).unwrap(), marker);
    }
}

#[test]
fn standalone_store_uses_same_v1_through_v4_migration_and_reopens() {
    // None represents the existing unmarked annotated standalone layout (v3).
    for version in [None, Some(1), Some(2), Some(3), Some(4)] {
        let root = tempfile::tempdir().unwrap();
        let session = SessionId::now_v7();
        let segment = SegmentId::from_u128(1);
        let dir = root.path().join(session.to_string());
        fs::create_dir_all(&dir).unwrap();
        let source = if version.is_some_and(|v| v <= 2) {
            V1
        } else {
            V4
        };
        let path = dir.join(format!("{segment}.jsonl"));
        fs::write(&path, source).unwrap();
        if let Some(version) = version {
            fs::write(dir.join("session-schema.json"), version.to_string()).unwrap();
        }
        let store = FsStore::new(root.path()).unwrap();
        let entries = store.read_all(session, segment).unwrap();
        for entry in entries {
            entry.validate_input_metadata().unwrap();
        }
        assert_eq!(
            fs::read_to_string(dir.join("session-schema.json"))
                .unwrap()
                .trim(),
            "6"
        );
        let once = fs::read(&path).unwrap();
        drop(store);
        FsStore::new(root.path()).unwrap();
        assert_eq!(fs::read(&path).unwrap(), once);
    }
}

#[test]
fn compaction_origin_upgrade_is_retained_only_for_pre_v4_sources() {
    for version in [3, 4] {
        let root = tempfile::tempdir().unwrap();
        let creation = seed(
            LoggedSessionHistoryOrigin::DerivedSummary,
            true,
            crate::LoggedRole::System,
            "[Compacted context summary]\n\nold summary",
        );
        let inherited = seed(
            LoggedSessionHistoryOrigin::DerivedSummary,
            false,
            crate::LoggedRole::System,
            "[Compacted context summary]\n\nold summary",
        );
        let (session, segment) =
            write_worker(root.path(), version, &encode(&[creation, inherited]));
        let store = WorkerSessionStore::new(root.path()).unwrap();
        for record in store.read_all(session, segment).unwrap() {
            let LogEntry::AnnotatedSegmentStart { history, .. } = record else {
                panic!()
            };
            let metadata = &history[0].metadata;
            assert_eq!(metadata.entry_id.0, "summary");
            assert_eq!(metadata.derivation.as_ref().unwrap().sources[0].0, "source");
            assert_eq!(
                metadata.origin,
                if version == 3 {
                    LoggedSessionHistoryOrigin::CompactionSummary
                } else {
                    LoggedSessionHistoryOrigin::DerivedSummary
                }
            );
            assert_eq!(
                metadata.input_metadata.as_ref().unwrap().usage().compaction,
                if version == 3 {
                    InputCompactionUse::OpeningSummary
                } else {
                    InputCompactionUse::Retain
                }
            );
        }
    }
}

#[test]
fn standalone_preflight_and_unsupported_marker_leave_sources_unchanged() {
    for version in [4, 99] {
        let root = tempfile::tempdir().unwrap();
        let session = SessionId::now_v7();
        let dir = root.path().join(session.to_string());
        fs::create_dir_all(&dir).unwrap();
        let first = dir.join(format!("{}.jsonl", SegmentId::from_u128(1)));
        let later = dir.join(format!("{}.jsonl", SegmentId::from_u128(2)));
        fs::write(&first, V4).unwrap();
        fs::write(&later, "{broken-json}\n").unwrap();
        let marker = version.to_string();
        fs::write(dir.join("session-schema.json"), &marker).unwrap();
        assert!(FsStore::new(root.path()).is_err());
        assert_eq!(fs::read(&first).unwrap(), V4.as_bytes());
        assert_eq!(fs::read_to_string(&later).unwrap(), "{broken-json}\n");
        assert_eq!(
            fs::read_to_string(dir.join("session-schema.json")).unwrap(),
            marker
        );
    }
}

#[test]
fn current_v5_rejects_all_legacy_feature_kinds_without_rewriting_sources() {
    for line in V4.lines().take(5) {
        // Current serde, writable open and read-only restore share the same
        // current wire contract. None may dispatch to the old Feature decoder.
        assert!(serde_json::from_str::<LogEntry>(line).is_err());
        let bytes = format!("{line}\n");
        let root = tempfile::tempdir().unwrap();
        let (session, segment) = write_worker(root.path(), 6, bytes.as_bytes());
        let path = root
            .path()
            .join("segments")
            .join(format!("{segment}.jsonl"));
        let marker = fs::read(root.path().join("session.json")).unwrap();
        let readonly = WorkerSessionStore::open_read_only(root.path()).unwrap();
        assert!(readonly.read_all_read_only(session, segment).is_err());
        assert!(WorkerSessionStore::new(root.path()).is_err());
        assert_eq!(fs::read(&path).unwrap(), bytes.as_bytes());
        assert_eq!(fs::read(root.path().join("session.json")).unwrap(), marker);

        let standalone = tempfile::tempdir().unwrap();
        let dir = standalone.path().join(session.to_string());
        fs::create_dir_all(&dir).unwrap();
        let path = dir.join(format!("{segment}.jsonl"));
        fs::write(&path, &bytes).unwrap();
        fs::write(dir.join("session-schema.json"), "5").unwrap();
        assert!(FsStore::new(standalone.path()).is_err());
        assert_eq!(fs::read(&path).unwrap(), bytes.as_bytes());
        assert_eq!(
            fs::read_to_string(dir.join("session-schema.json")).unwrap(),
            "5"
        );
    }
}

#[test]
fn v1_v2_feature_wire_uses_the_same_typed_payloads_and_stable_legacy_identity() {
    let segment = SegmentId::from_u128(42);
    for version in [1, 2] {
        for (index, line) in V4.lines().take(5).enumerate() {
            let annotated: Value = serde_json::from_str(line).unwrap();
            let wire = json!({
                "kind": "system_item", "ts": annotated["ts"],
                "item": annotated["entry"]["item"],
                "extensions": [{"domain":"old-owner", "payload":{"kept":true}}],
            })
            .to_string();
            let entry = decode_entry(version, &wire, SessionId::nil(), segment, index).unwrap();
            let retry = decode_entry(version, &wire, SessionId::nil(), segment, index).unwrap();
            assert_eq!(encode(&[entry.clone()]), encode(&[retry]));
            let LogEntry::AnnotatedSystemItem {
                ts,
                entry,
                extensions,
            } = entry
            else {
                panic!()
            };
            assert_eq!(ts, annotated["ts"].as_u64().unwrap());
            assert!(matches!(entry.item, SystemItem::Input { .. }));
            assert_eq!(
                entry.item.history_text(),
                annotated["entry"]["item"]["body"].as_str().unwrap()
            );
            assert_eq!(
                entry.metadata.entry_id,
                legacy_metadata(segment, index, 0).entry_id
            );
            assert_eq!(
                entry.metadata.origin,
                LoggedSessionHistoryOrigin::LegacyUnknown
            );
            assert!(entry.metadata.derivation.is_none());
            assert_eq!(extensions[0].domain, "old-owner");
            assert_eq!(extensions[0].payload, json!({"kept":true}));
            let LogEntry::AnnotatedSystemItem { entry: v4, .. } =
                decode_entry(4, line, SessionId::nil(), segment, index).unwrap()
            else {
                panic!()
            };
            assert_eq!(entry.metadata.input_metadata, v4.metadata.input_metadata);
        }
    }
}

#[test]
fn migration_rejects_malformed_typed_feature_fields_instead_of_retaining_unchecked_json() {
    let mut items: Vec<Value> = V4
        .lines()
        .take(5)
        .map(|line| serde_json::from_str::<Value>(line).unwrap()["entry"]["item"].clone())
        .collect();
    items[0]["snapshot_sha256"] = json!(17);
    items[1]["prompt_provenance"] = json!({"logical_name":"missing digests"});
    items[2]["behavior_md"] = json!(["not a string"]);
    items[3]["name"] = json!({"not":"a name"});
    items[4]["result"]["status"] = json!("unsupported_status");
    for version in 1..=4 {
        for item in &items {
            let wire = if version <= 2 {
                json!({"kind":"system_item", "ts":1, "item":item})
            } else {
                json!({"kind":"annotated_system_item", "ts":1, "entry":{
                    "item":item, "metadata":{
                        "entry_id":"malformed-id", "origin":{"kind":"legacy_unknown"},
                    },
                }})
            }
            .to_string();
            assert!(decode_entry(version, &wire, SessionId::nil(), SegmentId::nil(), 0).is_err());
        }
    }
}

#[test]
fn frozen_behavior_counter_is_accepted_only_at_the_old_schema_boundary() {
    for version in 1..=4 {
        let item = json!({
            "kind":"subject_behavior_refresh", "body":"exact archived body",
            "behavior_revision":7,
        });
        let wire = if version <= 2 {
            json!({"kind":"system_item", "ts":1, "item":item})
        } else {
            json!({"kind":"annotated_system_item", "ts":1, "entry":{
                "item":item, "metadata":{
                    "entry_id":"behavior-id", "origin":{"kind":"legacy_unknown"},
                },
            }})
        }
        .to_string();
        assert!(serde_json::from_str::<LogEntry>(&wire).is_err());
        let LogEntry::AnnotatedSystemItem { entry, .. } =
            decode_entry(version, &wire, SessionId::nil(), SegmentId::nil(), 0).unwrap()
        else {
            panic!()
        };
        assert_eq!(entry.item.history_text(), "exact archived body");
        let payload = entry
            .metadata
            .input_metadata
            .as_ref()
            .unwrap()
            .feature_payload()
            .unwrap();
        let typed: SubjectBehaviorPayload = payload.decode("subject:behavior", 1).unwrap();
        assert_eq!(typed.behavior_md, "");
        assert!(typed.prompt_provenance.is_none());
        assert_eq!(
            serde_json::to_value(typed).unwrap(),
            json!({
                "behavior_md":"", "prompt_provenance":null,
            })
        );
    }
}

#[test]
fn current_schema_rejects_generic_input_without_metadata_instead_of_migrating_it() {
    let mut missing: Value = serde_json::from_str(V4.lines().last().unwrap()).unwrap();
    missing["entry"]["metadata"]
        .as_object_mut()
        .unwrap()
        .remove("system_input");
    let bytes = format!("{}\n", missing);
    let root = tempfile::tempdir().unwrap();
    let (_, segment) = write_worker(root.path(), 6, bytes.as_bytes());
    assert!(WorkerSessionStore::new(root.path()).is_err());
    assert_eq!(
        fs::read(
            root.path()
                .join("segments")
                .join(format!("{segment}.jsonl"))
        )
        .unwrap(),
        bytes.as_bytes()
    );
    assert_marker(root.path(), 6);
}

const V5: &str = include_str!("fixtures/v5-role-metadata.jsonl");

#[test]
fn v5_metadata_and_derived_tool_context_upgrade_without_changing_roles_or_original_evidence() {
    for standalone in [false, true] {
        let root = tempfile::tempdir().unwrap();
        let (session, segment) = if standalone {
            let session = SessionId::now_v7();
            let segment = SegmentId::now_v7();
            let dir = root.path().join(session.to_string());
            fs::create_dir_all(&dir).unwrap();
            fs::write(dir.join("session-schema.json"), b"5").unwrap();
            fs::write(dir.join(format!("{segment}.jsonl")), V5).unwrap();
            (session, segment)
        } else {
            write_worker(root.path(), 5, V5.as_bytes())
        };
        let entries = if standalone {
            FsStore::new(root.path())
                .unwrap()
                .read_all(session, segment)
                .unwrap()
        } else {
            WorkerSessionStore::new(root.path())
                .unwrap()
                .read_all(session, segment)
                .unwrap()
        };
        let originals: Vec<Value> = V5
            .lines()
            .map(|line| serde_json::from_str(line).unwrap())
            .collect();
        assert_eq!(entries.len(), originals.len());
        for (index, (entry, old)) in entries.iter().zip(originals).enumerate() {
            let wire = serde_json::to_value(entry).unwrap();
            assert_eq!(wire["ts"], old["ts"]);
            assert_eq!(wire["entry"]["item"], old["entry"]["item"]);
            for field in ["entry_id", "origin", "derivation"] {
                assert_eq!(
                    wire["entry"]["metadata"][field],
                    old["entry"]["metadata"][field]
                );
            }
            let metadata = &wire["entry"]["metadata"];
            if index == 0 {
                assert_eq!(
                    metadata["input_metadata"],
                    old["entry"]["metadata"]["system_input"]
                );
                assert_eq!(
                    metadata["input_metadata"]["feature_payload"]["value"]["system_input"],
                    "opaque owner field must not be renamed"
                );
            } else if index < 3 {
                assert!(
                    metadata.get("input_metadata").is_none(),
                    "ordinary model Tool originals must not acquire exclusion policy"
                );
            } else {
                assert_eq!(
                    metadata["input_metadata"]["usage"],
                    json!({
                        "recording_material":"exclude", "memory_evidence":"exclude", "observation":"hidden", "compaction":"retain"
                    })
                );
            }
        }
        let before = encode(&entries);
        let reopened = if standalone {
            FsStore::new(root.path())
                .unwrap()
                .read_all(session, segment)
                .unwrap()
        } else {
            WorkerSessionStore::new(root.path())
                .unwrap()
                .read_all(session, segment)
                .unwrap()
        };
        assert_eq!(encode(&reopened), before);
    }
}

#[test]
fn legacy_metadata_alias_conflict_fails_preflight_without_dropping_either_value() {
    let mut bad: Value = serde_json::from_str(V5.lines().next().unwrap()).unwrap();
    bad["entry"]["metadata"]["input_metadata"] = bad["entry"]["metadata"]["system_input"].clone();
    for version in [4, 5] {
        let root = tempfile::tempdir().unwrap();
        let (_, segment) = write_worker(root.path(), version, V5.as_bytes());
        let path = root
            .path()
            .join("segments")
            .join(format!("{segment}.jsonl"));
        let later = root
            .path()
            .join("segments")
            .join(format!("{}.jsonl", SegmentId::from_u128(2)));
        let bad_bytes = format!("{bad}\n");
        fs::write(&later, &bad_bytes).unwrap();
        assert!(WorkerSessionStore::new(root.path()).is_err());
        assert_eq!(fs::read(path).unwrap(), V5.as_bytes());
        assert_eq!(fs::read(later).unwrap(), bad_bytes.as_bytes());
        assert_marker(root.path(), version);
    }
}
